Refactor this helper into TypeScript:

function groupBy(items, key) {
  return items.reduce((out, item) => {
    (out[item[key]] ||= []).push(item);
    return out;
  }, {});
}

Provide a generic type-safe version and three focused tests covering an empty input, a missing key value, and two items sharing a key. State your chosen behavior for missing keys.

output.text:
Here's a small, strict version. It fixes the original bug where `item[key] === undefined` silently created a `"undefined"` bucket.

### Generic implementation

**Chosen behavior for missing keys:** If `item[key]` is `null` or `undefined`, the item is **skipped** and not included in any group. Rationale: avoids polluting the result with a coerced `"undefined"` key. If you need to keep them, normalize before calling.

```ts
// groupBy.ts
type PropertyKey = string | number | symbol;

// Only allow keys whose value can be a property key (or optional version)
type GroupableKeys<T> = {
  [K in keyof T]: T[K] extends PropertyKey | null | undefined ? K : never
}[keyof T];

export function groupBy<T, K extends GroupableKeys<T>>(
  items: readonly T[],
  key: K
): Record<string, T[]> {
  const out: Record<string, T[]> = {};

  for (const item of items) {
    const raw = item[key];
    if (raw == null) continue; // <-- explicit missing-key policy

    const groupKey = String(raw as PropertyKey);
    (out[groupKey] ??= []).push(item);
  }

  return out;
}
```

> Typed to `Record<string, T[]>` intentionally. If you want literal key inference you can change the return to `Record<Extract<T[K], PropertyKey> & {}, T[]>` but for a library this is more ergonomic and doesn't lie about runtime `String()` coercion.

### Tests that document behavior

```ts
// groupBy.test.ts
import { describe, it, expect } from 'vitest';
import { groupBy } from './groupBy';

type Item = { cat?: string; id: number };

describe('groupBy', () => {
  it('empty input -> empty object', () => {
    expect(groupBy([] as Item[], 'cat')).toEqual({});
  });

  it('missing key value -> item skipped', () => {
    const items: Item[] = [
      { cat: 'a', id: 1 },
      { id: 2 }, // cat is missing
      { cat: undefined, id: 3 }, // cat is explicitly undefined
    ];

    const result = groupBy(items, 'cat');

    // only 'a' group exists, no "undefined" bucket
    expect(result).toEqual({
      a: [{ cat: 'a', id: 1 }],
    });
    expect(Object.keys(result)).not.toContain('undefined');
  });

  it('two items sharing a key -> grouped together', () => {
    const items: Item[] = [
      { cat: 'x', id: 1 },
      { cat: 'x', id: 2 },
      { cat: 'y', id: 3 },
    ];

    const result = groupBy(items, 'cat');

    expect(result).toEqual({
      x: [
        { cat: 'x', id: 1 },
        { cat: 'x', id: 2 },
      ],
      y: [{ cat: 'y', id: 3 }],
    });
  });
});
```

